ALTER TABLE public.interview_sessions ADD COLUMN predecessor_id uuid REFERENCES public.interview_sessions(id);
CREATE FUNCTION public.revise_interview(sid uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.interview_sessions; aid uuid; nid uuid; src record; BEGIN IF NOT public.can_edit_workspace() THEN RAISE EXCEPTION 'Only analysts and admins revise analyses'; END IF; PERFORM pg_advisory_xact_lock(710112026); SELECT * INTO s FROM public.interview_sessions WHERE id=sid FOR UPDATE; INSERT INTO public.role_analysis_versions(job_role_id,version_number) SELECT s.job_role_id,coalesce(max(version_number),0)+1 FROM public.role_analysis_versions WHERE job_role_id=s.job_role_id RETURNING id INTO aid; INSERT INTO public.interview_sessions(job_role_id,analysis_version_id,purposes,role_state,incumbents,locations,source_types,custom_output,is_fictional,predecessor_id) VALUES(s.job_role_id,aid,s.purposes,s.role_state,s.incumbents,s.locations,s.source_types,s.custom_output,s.is_fictional,s.id) RETURNING id INTO nid; FOR src IN SELECT * FROM public.interview_sources WHERE session_id=sid LOOP INSERT INTO public.interview_sources(session_id,name,source_type,user_id) VALUES(nid,src.name,src.source_type,src.user_id); END LOOP; RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.revise_interview(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.revise_interview(uuid) TO authenticated;
