('20000000-0000-0000-0000-000000000013','20000000-0000-0000-0000-000000000001','WH-B1','Task — incumbent','sme_interview','Assign picking lanes every shift; importance 5; errors delay dispatch and increase safety risks; 30% of time; learned on the job.','Morgan Lee (fictional)'),
('20000000-0000-0000-0000-000000000014','20000000-0000-0000-0000-000000000001','WH-B2','Task — supervisor','sme_interview','Assign picking lanes every shift; importance 5; errors delay dispatch and increase safety risks; 30% of time; learned on the job.','Alex Rivera (fictional)'),
('20000000-0000-0000-0000-000000000015','20000000-0000-0000-0000-000000000001','WH-H1','Standards — incumbent','sme_interview','Success is safe dispatch with accurate picks; target 98% picking accuracy; after 6–12 months independently coordinates a shift.','Morgan Lee (fictional)'),
